#if defined(_MSC_VER) && !defined(__clang__)
static inline uint32_t moe_atomic_load_acquire_u32(const uint32_t * p) {
    const uint32_t v = *static_cast<const volatile uint32_t *>(p);
    std::atomic_signal_fence(std::memory_order_acquire);
#if defined(_M_ARM64) || defined(_M_ARM64EC)
    std::atomic_thread_fence(std::memory_order_acquire);
#endif
    return v;
}
static inline void moe_atomic_store_release_u32(uint32_t * p, uint32_t v) {
#if defined(_M_ARM64) || defined(_M_ARM64EC)
    std::atomic_thread_fence(std::memory_order_release);
#endif
    std::atomic_signal_fence(std::memory_order_release);
    *static_cast<volatile uint32_t *>(p) = v;
}
#else
static inline uint32_t moe_atomic_load_acquire_u32(const uint32_t * p) {
    return __atomic_load_n(p, __ATOMIC_ACQUIRE);
}
static inline void moe_atomic_store_release_u32(uint32_t * p, uint32_t v) {
    __atomic_store_n(p, v, __ATOMIC_RELEASE);
}
#endif

// GGML_TRACE (ggml-backend.h) - a span on the trace timeline from construction to scope end.
// With the trace off, the constructor is one start-up-chosen check (ggml_trace_on() is a function-local static) and the destructor
// tests a zero.
struct moe_trace_span {
    int64_t t0;
    int     lane;
    const char * name;
    int64_t arg;
    moe_trace_span(int lane_, const char * name_, int64_t arg_) : t0(ggml_trace_on() ? ggml_time_us() : 0), lane(lane_), name(name_), arg(arg_) {}
    ~moe_trace_span() { if (t0) { ggml_trace_event(lane, name, t0, ggml_time_us(), arg); } }
};

// TEST ONLY: MOE_STREAM_TEST_AUX_CPUS=<a>-<b> pins the engine's own threads (the SSD readers, the guess helper,
// the VRAM-follow uploader) to CPUs a..b, read once - a diagnosis of where the plain matmuls lose RAM speed (the compute threads go to their CPUs
// with -C / --cpu-range / --cpu-strict). Linux only; any failure is printed.
static void moe_stream_test_aux_cpus(std::thread & t, const char * what) {
#if defined(__linux__)
    static int lo = -2, hi = -1;
    if (lo == -2) {
        const char * e = getenv("MOE_STREAM_TEST_AUX_CPUS");
        if (!e || sscanf(e, "%d-%d", &lo, &hi) != 2 || lo < 0 || hi < lo || hi >= CPU_SETSIZE) {
            lo = -1;
        } else {
            fprintf(stderr, "llama_moe_stream: TEST ONLY: MOE_STREAM_TEST_AUX_CPUS: the engine's threads on CPUs %d-%d\n", lo, hi);
        }
    }
    if (lo < 0 || !t.joinable()) {
        return;
    }
    cpu_set_t cs;
    CPU_ZERO(&cs);
    for (int c = lo; c <= hi; c++) {
        CPU_SET(c, &cs);
    }
    const int rc = pthread_setaffinity_np(t.native_handle(), sizeof(cs), &cs);
    if (rc != 0) {
        fprintf(stderr, "llama_moe_stream: TEST ONLY: MOE_STREAM_TEST_AUX_CPUS: %s: pthread_setaffinity_np failed (%d)\n", what, rc);
    }
#else
    (void) t; (void) what;
#endif
}

